 @override Widget build(BuildContext context)=>Column(children:[Expanded(child:messages.isEmpty?const Center(child:Padding(padding:EdgeInsets.all(26),child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(Icons.auto_awesome,size:48,color:cyan),SizedBox(height:16),Text('What can we create today?',style:TextStyle(fontSize:23,fontWeight:FontWeight.bold),textAlign:TextAlign.center),SizedBox(height:8),Text('Ask, write, plan, brainstorm and solve problems.',textAlign:TextAlign.center,style:TextStyle(color:Colors.white60))])):ListView.builder(controller:list,padding:const EdgeInsets.all(14),itemCount:messages.length+(busy?1:0),itemBuilder:(c,i){if(i>=messages.length)return const Padding(padding:EdgeInsets.all(12),child:CircularProgressIndicator());final m=messages[i];final user=m.role=='user';return Align(alignment:user?Alignment.centerRight:Alignment.centerLeft,child:Container(constraints:const BoxConstraints(maxWidth:600),margin:const EdgeInsets.symmetric(vertical:5),padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:user?const Color(0xFF123A65):panel,borderRadius:BorderRadius.circular(18)),child:SelectableText(m.text,style:const TextStyle(height:1.45))));})),if(error!=null)Padding(padding:const EdgeInsets.all(8),child:Text(error!,style:const TextStyle(color:Colors.redAccent))),SafeArea(top:false,child:Padding(padding:const EdgeInsets.all(10),child:Row(children:[Expanded(child:TextField(controller:input,minLines:1,maxLines:5,onSubmitted:(_)=>send(),decoration:const InputDecoration(hintText:'Message Devora…'))),const SizedBox(width:8),IconButton.filled(onPressed:busy?null:send,style:IconButton.styleFrom(backgroundColor:blue),icon:const Icon(Icons.arrow_upward))])))]);
}
